// A Runner card whose entry has HoldFacts.hostedInstall (Madani: "Once per turn -> 0 credits: Install 1 hosted program
// (paying its install cost)") lets the Runner install a program hosted faceup on it with no click, in any paid ability
// window (9.2.7, 9.5.2: in a run 6.9.1e, 6.9.2b, 6.9.3b, 6.9.4b and e; on the Corp's turn 5.6.2a, 5.6.3b), `perTurn`
// times a turn (9.3.6g; each player's turn is a turn, 5.1.1), paying its install cost (1.16.6a, 8.5.11). The hosted
// programs are faceup, so public (10.2.2); the grip stays out.
//
// How the walk carries it: a choice at the start, with one board. The walk's board has every hosted program the walk
// reads (breakers, trojans, programs with hold facts) installed at once, a trojan on every ice of the asked server
// (copies); a way is the set the Runner installs, no larger than the uses left before the walked turn ends, and the walk
// starts with the others `gone` (the walk's trashed cards: their plans, subtypes, counters and payments are not read),
// its install costs added to the need. So the break plans and subtypes are gathered once per board, as now (the subtypes
// already for every set of the subtype-giving cards gone), the walk's node keys are unchanged (`gone` is in them), and
// the ways of one question share its memos. Bounds, all toward the Runner: one trojan may stand on several ice; memory is
// not checked (8.5.6c, 3.9.3b: an install over the limit trashes programs); every install is late (made after the rezzes
// before its first use: no purge or trojan trash at a rez reaches it); a counter program (Botulus, Tranquilizer: "When you
// install this program and when your turn begins", the install counters read from runnerTurnStart) has the walked turn's
// start counter too when a use falls before that turn begins; a program left out still adds its turn money to the budget
// (runnerEarnings reads the board's rig: none of the pool's walked programs has any but Coalescence's counters).
// The server holds against a rez set only if no way gets in (the set is the Corp's, the way the Runner's after it: some
// set holds against every way). `need` is the least over the ways. No program to install: null, the walk as before.

/** The board with every walked hosted program installed, and the Runner's ways: the rig indexes left out, the install costs. */
interface HostedWays {
  board: GameState;
  ways: { gone: number[]; cost: number }[];
}

/** The Runner's ways of installing hosted programs before or during the walk ('turn': its next turn; 'rest': the rest of this one; 'run': the run under way); once per board. */
function hostedWays(state: GameState, server: string, kind: 'turn' | 'rest' | 'run'): HostedWays | null {
  return memo(state, `hostedWays:${kind}:${server}`, () => waysOf(state, server, kind));
}

/** A program the walk reads once installed: a breaker, a trojan (its host ice), or one with hold facts. */
const walkedProgram = (c: CardInstance): boolean => {
  const def = cardDef(c);
  return def.type_code === 'program' && (/icebreaker/i.test(def.keywords ?? '') || !!getCardScript(c.cardCode)?.installsOnIce || !!CARDS[c.cardCode]?.holdFacts);
};

/** Every subset of `list` of at most `k`, the empty one first. */
function subsetsUpTo<T>(list: T[], k: number): T[][] {
  let out: T[][] = [[]];
  for (let n = 1; n <= Math.min(k, list.length); n++) out = [...out, ...choose(list, n)];
  return out;
}

function waysOf(state: GameState, server: string, kind: 'turn' | 'rest' | 'run'): HostedWays | null {
  const { programs, hardware, resources } = state.runner.rig;
  const ice = state.corp.servers[server]?.ice ?? [];
  const fresh = kind === 'turn';
  const added: CardInstance[] = [];
  /** By hosted program: the rig indexes of its copies on the board. */
  const at = new Map<string, number[]>();
  let combos: CardInstance[][] = [[]];
  for (const h of [...programs, ...hardware, ...resources]) {
    const f = CARDS[h.cardCode]?.holdFacts?.hostedInstall;
    if (!f) continue;
    const left = Math.max(0, f.perTurn - turnFlag(state, abilityUsedKey(h.instanceId, f.ability)));
    // 'turn': the rest of this turn, the Corp's turn between when asked on the Runner's, then the walked turn
    const early = fresh ? left + (state.activePlayer === 'runner' ? f.perTurn : 0) : 0;
    const uses = fresh ? early + f.perTurn : left;
    // A trojan needs an ice; one on another server's ice is not read by this server's walk
    const list = (h.hostedCards ?? []).filter(walkedProgram).filter(c => !getCardScript(c.cardCode)?.installsOnIce || ice.length > 0);
    if (!uses || !list.length) continue;
    for (const c of list) {
      const t = CARDS[c.cardCode]?.holdFacts?.runnerTurnStart?.counters;
      const tokens: Record<string, number> = { ...((c.tokens ?? {}) as Record<string, number>) };
      // Its install counters; a fresh start adds the turn start's (walkStart): installed before it, both; during it, the install's only
      if (t) tokens[t.kind] = (tokens[t.kind] ?? 0) + (fresh && !early ? 0 : t.n);
      const base = { ...c, isRezzed: true, tokens, holdLate: true as const } as CardInstance;
      const copies = getCardScript(c.cardCode)?.installsOnIce ? ice.map(i => ({ ...base, instanceId: `${c.instanceId}@${i.instanceId}`, hostedOnId: i.instanceId })) : [{ ...base, hostedOnId: undefined }];
      at.set(c.instanceId, copies.map((_, k) => programs.length + added.length + k));
      added.push(...copies);
    }
    const subs = subsetsUpTo(list, uses);
    combos = combos.flatMap(x => subs.map(picks => [...x, ...picks]));
  }
  if (!added.length) return null;
  const hostedIds = new Set(at.keys());
  const strip = (c: CardInstance): CardInstance => (c.hostedCards?.some(h => hostedIds.has(h.instanceId)) ? { ...c, hostedCards: c.hostedCards.filter(h => !hostedIds.has(h.instanceId)) } : c);
  const r = state.runner.rig;
  const board: GameState = { ...state, runner: { ...state.runner, rig: { ...r, programs: [...r.programs.map(strip), ...added], hardware: r.hardware.map(strip), resources: r.resources.map(strip) } } };
  const ways = combos.map(picks => {
    const chosen = new Set(picks.map(c => c.instanceId));
    const gone = [...at.entries()].flatMap(([id, idx]) => (chosen.has(id) ? [] : idx)).sort((a, b) => a - b);
    return { gone, cost: picks.reduce((n, c) => n + (cardDef(c).cost ?? 0), 0) };
  });
  return { board, ways };
}

/** A ways question's answer (as TurnAnswer): the set that holds against every way, or the one that asks the most. */
interface WaysAnswer {
  holds: boolean;
  set: number;
  need: number;
  entries?: number;
  memos?: WalkMemos;
}
const waysAnswers = new WeakMap<object, Map<string, WaysAnswer>>();

/** The question as one way starts it: the others gone. */
const wayInput = <T extends TurnInput>(q: T, gone: number[]): T => ({ ...q, first: { ...q.first, gone } });

/** The search over the ways (pure: it reads the question and the ways alone). */
function solveWays(q: TurnQuestion, ways: HostedWays['ways']): WaysAnswer {
  holdCacheStats.searched++;
  const memos = walkMemos();
  const inputs = ways.map(w => wayInput(q, w.gone));
  let most = -Infinity;
  let mostSet = -1;
  for (let k = 0; k < q.sets.length; k++) {
    if (!q.sets[k].affordable) continue;
    const target = [setTarget(q, k)];
    let least = Infinity;
    let gets = false;
    // In subset order (none first); once a way gets in and the least need is no more than the most asked so far, this set
    // can change neither the answer nor `need`, and its other ways are not walked (exact)
    for (let c = 0; c < ways.length && !(gets && least <= most); c++) {
      const extra = q.sets[k].price + ways[c].cost;
      const need = turnNeed(inputs[c], target, memos.one) + extra;
      least = Math.min(least, need);
      if (!gets && (need <= q.budget || turnNeed(inputs[c], target, memos.turn, true) + extra <= q.budget)) gets = true;
    }
    if (!gets) return { holds: true, set: k, need: least };
    if (least > most) [most, mostSet] = [least, k];
  }
  return { holds: false, set: mostSet < 0 ? q.sets.findIndex(x => x.mask === 0) : mostSet, need: most === -Infinity ? 0 : most, memos };
}

/** walkPick with ways (hostedWays): a set holds only against every way; cached per decision as walkPick's answers. */
function walkWays(server: string, corpCredits: number, from: TurnFrom, picked: string[] | undefined, hw: HostedWays): Hold {
  const q = turnQuestion(hw.board, server, corpCredits, from, picked);
  const { ways } = hw;
  holdCacheStats.asked++;
  const anchor = pricing().anchor;
  let cache = anchor ? waysAnswers.get(anchor) : undefined;
  if (anchor && !cache) waysAnswers.set(anchor, (cache = new Map()));
  const key = cache ? questionKey({ q, ways }) : '';
  let a = cache?.get(key);
  if (!a) {
    a = solveWays(q, ways);
    cache?.set(key, a);
  }
  const ids = q.ice.slice(0, 10).filter((_, i) => q.sets[a!.set].mask & (1 << i)).map(c => c.id);
  const { budget } = q;
  const need = a.need;
  if (a.holds) return { holds: true, rez: ids, rezCost: q.sets[a.set].rez, need, budget, margin: need - budget, entries: 0 };
  const answer = a;
  return {
    holds: false,
    rez: null,
    rezCost: Infinity,
    need,
    budget,
    margin: need - budget,
    get entries() {
      if (answer.entries === undefined) {
        // The most runs one way's turn gets in on, against the set that asks the most (sequenceEntries; a way's costs once)
        const target = setTarget(q, answer.set);
        const memos = answer.memos ?? walkMemos();
        let most = q.maxClicks > 0 ? 1 : 0;
        for (const w of ways) {
          const input = wayInput(q, w.gone);
          let e = 0;
          while (e < q.maxClicks && passes(input, Array(e + 1).fill(target), (e + 1) * q.sets[answer.set].price + w.cost, q.budget, memos)) e++;
          most = Math.max(most, e);
        }
        answer.entries = most;
        answer.memos = undefined;
      }
      return answer.entries;
    },
  };
}

/** walkThisRun with ways: the cheapest set that holds against every way, else the one that asks the most. */
function runWays(server: string, opts: HoldOptions, hw: HostedWays): Hold {
  const q = runQuestion(hw.board, server, opts);
  const { budget } = q;
  const none: Hold = { holds: false, rez: null, rezCost: Infinity, need: 0, budget, margin: -budget, entries: 1 };
  if (q.none || !q.board || !q.first) return none;
  let best = Infinity;
  let bestSet: string[] | null = null;
  let bestNeed = 0;
  let mostNeed = -Infinity;
  for (const set of q.sets) {
    if (set.cost >= best) continue;
    const up = new Set(set.up);
    const skipped = new Set(set.skipped);
    const ice = q.ice.map(c => ({ ...c, inS: up.has(c.id), bypassed: skipped.has(c.id) }));
    const walk = new Walk(q.board, [{ server: q.server, ice }], undefined, false);
    // Once the least need is within the budget and no more than the most asked so far, this set changes nothing (exact)
    let least = Infinity;
    for (let c = 0; c < hw.ways.length && !(least <= budget && least <= mostNeed); c++) least = Math.min(least, walk.fromIce({ ...q.first!, gone: hw.ways[c].gone }, q.pos) + hw.ways[c].cost);
    if (least > mostNeed) mostNeed = least;
    if (least > budget) {
      best = set.cost;
      bestSet = set.up;
      bestNeed = least;
    }
  }
  if (bestSet) return { holds: true, rez: bestSet, rezCost: best, need: bestNeed, budget, margin: bestNeed - budget, entries: 0 };
  const need = mostNeed === -Infinity ? 0 : mostNeed;
  return { ...none, need, margin: need - budget };
}

