/** The board with every walked hosted program installed, and the Runner's ways: the rig indexes left out, the install costs. */
interface HostedWays {
  board: GameState;
  ways: { gone: number[]; cost: number }[];
}

/** The Runner's ways of installing hosted programs before or during the walk ('turn': its next turn; 'rest': the rest of this one; 'run': the run under way); once per board. */
function hostedWays(state: GameState, server: string, kind: 'turn' | 'rest' | 'run'): HostedWays | null {
  return memo(state, `hostedWays:${kind}:${server}:${JSON.stringify(mhFlags())}`, () => waysOf(state, server, kind));
}

/** A program the walk reads once installed: a breaker, a trojan (its host ice), or one with hold facts. */
const walkedProgram = (c: CardInstance): boolean => {
  const def = cardDef(c);
  return def.type_code === 'program' && (/icebreaker/i.test(def.keywords ?? '') || !!getCardScript(c.cardCode)?.installsOnIce || !!CARDS[c.cardCode]?.holdFacts);
};

/** Every subset of `list` of at most `k`, the empty one first. */
function subsetsUpTo<T>(list: T[], k: number): T[][] {
  let out: T[][] = [[]];
  for (let n = 1; n <= Math.min(k, list.length); n++) out = [...out, ...choose(list, n)];
  return out;
}

/**
 * madani-hosted count 2, arm `onboard`: every walked hosted program read as installed, all at once, one way, nothing
 * charged (count 1's union board with nothing gone). The measuring script may tighten it, one bound at a time, through
 * globalThis.__mhFlags (count 2's classing ladder; never set in play): costs (every subset, its install cost added),
 * uses (at most the installs the timeline allows), memory (no way over the memory limit), oneIce (a trojan on one ice
 * only), notLate (a hosted install is not immune to a purge or Bumi), noCounters (no counter added at the install).
 */
interface MhFlags {
  costs?: boolean;
  uses?: boolean;
  memory?: boolean;
  oneIce?: boolean;
  notLate?: boolean;
  noCounters?: boolean;
}
const mhFlags = (): MhFlags => (globalThis as { __mhFlags?: MhFlags }).__mhFlags ?? {};

function waysOf(state: GameState, server: string, kind: 'turn' | 'rest' | 'run'): HostedWays | null {
  const FL = mhFlags();
  const { programs, hardware, resources } = state.runner.rig;
  const ice = state.corp.servers[server]?.ice ?? [];
  const fresh = kind === 'turn';
  const added: CardInstance[] = [];
  /** By hosted program: the rig indexes of its copies on the board. */
  const at = new Map<string, number[]>();
  const trojanIds = new Set<string>();
  let combos: CardInstance[][] = [[]];
  for (const h of [...programs, ...hardware, ...resources]) {
    const f = CARDS[h.cardCode]?.holdFacts?.hostedInstall;
    if (!f) continue;
    const left = Math.max(0, f.perTurn - turnFlag(state, abilityUsedKey(h.instanceId, f.ability)));
    const early = fresh ? left + (state.activePlayer === 'runner' ? f.perTurn : 0) : 0;
    const uses = FL.uses ? (fresh ? early + f.perTurn : left) : Infinity;
    const list = (h.hostedCards ?? []).filter(walkedProgram).filter(c => !getCardScript(c.cardCode)?.installsOnIce || ice.length > 0);
    if (!uses || !list.length) continue;
    for (const c of list) {
      const t = CARDS[c.cardCode]?.holdFacts?.runnerTurnStart?.counters;
      const tokens: Record<string, number> = { ...((c.tokens ?? {}) as Record<string, number>) };
      if (t && !FL.noCounters) tokens[t.kind] = (tokens[t.kind] ?? 0) + (fresh && !early ? 0 : t.n);
      const base = { ...c, isRezzed: true, tokens, ...(FL.notLate ? {} : { holdLate: true as const }) } as CardInstance;
      const trojan = !!getCardScript(c.cardCode)?.installsOnIce;
      if (trojan) trojanIds.add(c.instanceId);
      const copies = trojan ? ice.map(i => ({ ...base, instanceId: `${c.instanceId}@${i.instanceId}`, hostedOnId: i.instanceId })) : [{ ...base, hostedOnId: undefined }];
      at.set(c.instanceId, copies.map((_, k) => programs.length + added.length + k));
      added.push(...copies);
    }
    if (FL.costs) {
      const subs = subsetsUpTo(list, uses);
      combos = combos.flatMap(x => subs.map(picks => [...x, ...picks]));
    } else combos = combos.map(x => [...x, ...list]);
  }
  if (!added.length) return null;
  const hostedIds = new Set(at.keys());
  const strip = (c: CardInstance): CardInstance => (c.hostedCards?.some(h => hostedIds.has(h.instanceId)) ? { ...c, hostedCards: c.hostedCards.filter(h => !hostedIds.has(h.instanceId)) } : c);
  const r = state.runner.rig;
  const board: GameState = { ...state, runner: { ...state.runner, rig: { ...r, programs: [...r.programs.map(strip), ...added], hardware: r.hardware.map(strip), resources: r.resources.map(strip) } } };
  const limit = FL.memory ? memoryLimit(state) : Infinity;
  const mu = (c: CardInstance) => cardDef(c).memory_cost || 0;
  const ways: HostedWays['ways'] = [];
  for (const picks of combos) {
    if (state.runner.memoryUnitsUsed + picks.reduce((n, c) => n + mu(c), 0) > limit) continue;
    const chosen = new Set(picks.map(c => c.instanceId));
    const base = [...at.entries()].flatMap(([id, idx]) => (chosen.has(id) ? [] : idx));
    // oneIce: each chosen trojan on one ice, every placement a way
    let gones: number[][] = [base];
    if (FL.oneIce)
      for (const id of chosen)
        if (trojanIds.has(id)) {
          const idx = at.get(id)!;
          gones = gones.flatMap(g => idx.map(keep => [...g, ...idx.filter(x => x !== keep)]));
        }
    const cost = FL.costs ? picks.reduce((n, c) => n + (cardDef(c).cost ?? 0), 0) : 0;
    for (const g of gones) ways.push({ gone: g.sort((a, b) => a - b), cost });
  }
  if (!ways.length) ways.push({ gone: [...at.values()].flat().sort((a, b) => a - b), cost: 0 });
  return { board, ways };
}

/** A ways question's answer (as TurnAnswer): the set that holds against every way, or the one that asks the most. */
interface WaysAnswer {
  holds: boolean;
  set: number;
  need: number;
  entries?: number;
  memos?: WalkMemos;
}
const waysAnswers = new WeakMap<object, Map<string, WaysAnswer>>();

/** The question as one way starts it: the others gone. */
const wayInput = <T extends TurnInput>(q: T, gone: number[]): T => ({ ...q, first: { ...q.first, gone } });

/** The search over the ways (pure: it reads the question and the ways alone). */
function solveWays(q: TurnQuestion, ways: HostedWays['ways']): WaysAnswer {
  holdCacheStats.searched++;
  const memos = walkMemos();
  const inputs = ways.map(w => wayInput(q, w.gone));
  let most = -Infinity;
  let mostSet = -1;
  for (let k = 0; k < q.sets.length; k++) {
    if (!q.sets[k].affordable) continue;
    const target = [setTarget(q, k)];
    let least = Infinity;
    let gets = false;
    // In subset order (none first); once a way gets in and the least need is no more than the most asked so far, this set
    // can change neither the answer nor `need`, and its other ways are not walked (exact)
    for (let c = 0; c < ways.length && !(gets && least <= most); c++) {
      const extra = q.sets[k].price + ways[c].cost;
      const need = turnNeed(inputs[c], target, memos.one) + extra;
      least = Math.min(least, need);
      if (!gets && (need <= q.budget || turnNeed(inputs[c], target, memos.turn, true) + extra <= q.budget)) gets = true;
    }
    if (!gets) return { holds: true, set: k, need: least };
    if (least > most) [most, mostSet] = [least, k];
  }
  return { holds: false, set: mostSet < 0 ? q.sets.findIndex(x => x.mask === 0) : mostSet, need: most === -Infinity ? 0 : most, memos };
}

/** walkPick with ways (hostedWays): a set holds only against every way; cached per decision as walkPick's answers. */
function walkWays(server: string, corpCredits: number, from: TurnFrom, picked: string[] | undefined, hw: HostedWays): Hold {
  const q = turnQuestion(hw.board, server, corpCredits, from, picked);
  const { ways } = hw;
  holdCacheStats.asked++;
  const anchor = pricing().anchor;
  let cache = anchor ? waysAnswers.get(anchor) : undefined;
  if (anchor && !cache) waysAnswers.set(anchor, (cache = new Map()));
  const key = cache ? questionKey({ q, ways }) : '';
  let a = cache?.get(key);
  if (!a) {
    a = solveWays(q, ways);
    cache?.set(key, a);
  }
  const ids = q.ice.slice(0, 10).filter((_, i) => q.sets[a!.set].mask & (1 << i)).map(c => c.id);
  const { budget } = q;
  const need = a.need;
  if (a.holds) return { holds: true, rez: ids, rezCost: q.sets[a.set].rez, need, budget, margin: need - budget, entries: 0 };
  const answer = a;
  return {
    holds: false,
    rez: null,
    rezCost: Infinity,
    need,
    budget,
    margin: need - budget,
    get entries() {
      if (answer.entries === undefined) {
        // The most runs one way's turn gets in on, against the set that asks the most (sequenceEntries; a way's costs once)
        const target = setTarget(q, answer.set);
        const memos = answer.memos ?? walkMemos();
        let most = q.maxClicks > 0 ? 1 : 0;
        for (const w of ways) {
          const input = wayInput(q, w.gone);
          let e = 0;
          while (e < q.maxClicks && passes(input, Array(e + 1).fill(target), (e + 1) * q.sets[answer.set].price + w.cost, q.budget, memos)) e++;
          most = Math.max(most, e);
        }
        answer.entries = most;
        answer.memos = undefined;
      }
      return answer.entries;
    },
  };
}

